1	/* ecall dispatch: the "Set 1" syscalls a static glibc needs from _start to
2	 * printf+malloc+exit (ROADMAP_LINUX_RUNTIME.md U4). Reuses vplat's own
3	 * _write/_exit (already linked into vlinux via ../vplat_syscalls.c) and
4	 * mm.c's brk/mmap arenas rather than adding a second UART/SimControl path
5	 * or memory manager.
6	 *
7	 * Unknown syscalls are NOT fatal: glibc is designed to tolerate some optional
8	 * syscalls being unavailable (ROADMAP_LINUX_RUNTIME.md's own risk note about
9	 * riscv_hwprobe falling back to generic code), so an unimplemented number
10	 * prints once (grep-able) and returns -ENOSYS, same as real Linux would for
11	 * a syscall the running kernel does not implement -- it does not trap.
12	 */
13	#include "../ecall_hook.h"
14	#include "../htif_client.h"
15	
16	#include <stddef.h>
17	#include <stdint.h>
18	#include <stdio.h>
19	#include <sys/types.h>
20	
21	#include "linux_errno.h"
22	#include "mm.h"
23	
24	extern ssize_t _write(int fd, const void* ptr, size_t len);
25	extern ssize_t _read(int fd, void* buf, size_t len);
26	extern void _exit(int status) __attribute__((noreturn));
27	
28	/* trap.S register-save-frame slot indices (see ecall_hook.h). */
29	#define REG_A0 10
30	#define REG_A1 11
31	#define REG_A2 12
32	#define REG_A3 13
33	#define REG_A4 14
34	#define REG_A5 15
35	#define REG_A7 17
36	#define REG_MEPC 32
37	
