39	#define SYS_writev 66
40	#define SYS_exit 93
41	#define SYS_exit_group 94
42	#define SYS_set_tid_address 96
43	#define SYS_futex 98
44	#define SYS_set_robust_list 99
45	#define SYS_sched_yield 124
46	#define SYS_sched_getaffinity 123
47	#define SYS_sigaltstack 132
48	#define SYS_rt_sigaction 134
49	#define SYS_rt_sigprocmask 135
50	#define SYS_uname 160
51	#define SYS_getpid 172
52	#define SYS_getuid 174
53	#define SYS_geteuid 175
54	#define SYS_getgid 176
55	#define SYS_getegid 177
56	#define SYS_gettid 178
57	#define SYS_fcntl 25
58	#define SYS_ioctl 29
59	#define SYS_mprotect 226
60	#define SYS_munmap 215
61	#define SYS_mmap 222
62	#define SYS_mremap 216
63	#define SYS_brk 214
64	#define SYS_tgkill 131
