193	static int enosys_already_seen(unsigned long nr)
194	{
195	  if (nr >= 512) return 0; /* out of the table's range: always print */
196	  const unsigned long byte = nr / 8, bit = nr % 8;
197	  if (g_enosys_seen[byte] & (unsigned char) (1u << bit)) return 1;
198	  g_enosys_seen[byte] |= (unsigned char) (1u << bit);
199	  return 0;
