256	/* The HTIF host's stat/fstat/fstatat handlers only ever fill two fields
257	 * of whatever buffer address they are given: st_mode (u32 at byte offset
258	 * 4) and st_size (u64 at byte offset 16) -- a fixed micro-protocol, not a
259	 * whole-struct bounce (see andes_ae350.c andesim_store_guest_stat). vlinux
260	 * must translate those two fields into the app's actual glibc-shaped
261	 * struct stat/statx, which use different offsets entirely. */
262	static void host_stat_mode_size(size_t woff, unsigned int* mode,
263	                                unsigned long* size)
264	{
265	  /* htif_win_load is u64-load-only and requires an 8-aligned woff (see
266	   * htif_client.c: it dereferences a uint64_t* at WIN_DATA_VA+woff) --
267	   * QEMU's byte-addressable MMIO model tolerates a misaligned sub-8-byte
268	   * request silently, but the cycle-accurate RTL's real uncached-device
269	   * bus logic faults on it (load access fault, mcause=5). Load the whole
270	   * 24-byte aligned block in one 8-aligned call and extract st_mode
271	   * (bytes 4..7) / st_size (bytes 16..23) locally instead. */
272	  uint64_t raw[3];
273	  htif_win_load(raw, woff, sizeof raw);
274	  *mode = (unsigned int) (raw[0] >> 32); /* LE: byte 4..7 = upper 32 bits */
275	  *size = raw[2];                        /* LE: byte 16..23, already u64 */
276	}
277	
278	static void fill_stat_from_host(struct vlinux_stat* st, unsigned int mode,
279	                                unsigned long size)
280	{
281	  for (size_t i = 0; i < sizeof(*st); ++i) ((char*) st)[i] = 0;
282	  st->st_mode = mode;
283	  st->st_size = (long) size;
284	  st->st_nlink = 1;
285	  st->st_blksize = 4096;
286	  st->st_blocks = (long) ((size + 511) / 512);
287	}
