289	static long sys_openat(int dirfd, const char* path, int flags, int mode)
290	{
291	  const int nflags = linux_to_newlib_open_flags(flags);
292	  /* AT_FDCWD is openat's "resolve like open() would" case (POSIX): route
293	   * it through VH_SYS_OPEN, which threads mode correctly. VH_SYS_OPENAT's
294	   * host handler drops the mode argument entirely (its own arity -- see
295	   * andes_ae350.c case 20), so a real dirfd-relative O_CREAT open (not
296	   * exercised by any current fixture) is the one documented gap left by
297	   * this relay, same "loud, low-severity, documented" tier as U2's
298	   * staging-dir leak. */
299	  if (dirfd == AT_FDCWD)
300	    return htif_call_str(VH_SYS_OPEN, path, (uint64_t) nflags, (uint64_t) mode);
301	  if (htif_win_store_str(0, path) == (size_t) -1) return -EINVAL;
302	  return htif_syscall(VH_SYS_OPENAT, (uint64_t) dirfd, WIN_DATA_VA,
303	                      (uint64_t) nflags, 0);
304	}
