323	/* The one VH_SYS_FSTATAT host round trip both sys_fstatat and sys_statx
324	 * ride: path staged at window offset 0, then the host's mode+size fields
325	 * extracted from the scratch block right after it. stoff+24: room for
326	 * host_stat_mode_size's aligned scratch block after the path string, same
327	 * bound vplat's own _fstatat/_stat apply. On 0, *mode and *size are
328	 * filled; on any other return they are untouched. */
329	static long stat_host_roundtrip(int dirfd, const char* path, int flags,
330	                                unsigned int* mode, unsigned long* size)
331	{
332	  size_t stoff = htif_win_store_str(0, path);
333	  if (stoff == (size_t) -1 || stoff + 24 > WIN_DATA_SIZE) return -EINVAL;
334	  long r = htif_syscall(VH_SYS_FSTATAT, (uint64_t) dirfd, WIN_DATA_VA,
335	                        WIN_DATA_VA + stoff, (uint64_t) flags);
336	  if (r == 0) host_stat_mode_size(stoff, mode, size);
337	  return r;
338	}
