340	/* fstatat honors dirfd and AT_SYMLINK_NOFOLLOW natively on the host side
341	 * (its own fstatat() call), so both forward as-is -- no AT_FDCWD special
342	 * case needed here (unlike openat, this host handler already threads
343	 * every argument fstatat's real ABI has). This is also where glibc's
344	 * stat()/lstat() land: riscv64 has no bare stat/lstat syscalls. */
345	static long sys_fstatat(int dirfd, const char* path, struct vlinux_stat* buf,
346	                        int flags)
347	{
348	  unsigned int mode = 0; unsigned long size = 0;
349	  long r = stat_host_roundtrip(dirfd, path, flags, &mode, &size);
350	  if (r == 0) fill_stat_from_host(buf, mode, size);
351	  return r;
352	}
