354	/* statx: same host round trip as fstatat (mode+size only), translated
355	 * into struct statx. stx_mask reports ONLY the fields actually filled
356	 * (TYPE/MODE/NLINK/UID/GID/SIZE) -- per statx(2), a caller must not trust
357	 * a field whose mask bit is clear, so this is the correct "basic mask"
358	 * contract, not a shortcut: blksize/blocks are always-filled best-effort
359	 * (real filesystems provide them unconditionally per the man page), while
360	 * timestamps/ino stay zero and unclaimed since nothing here has them. */
361	static long sys_statx(int dirfd, const char* path, int flags,
362	                      struct vlinux_statx* buf)
363	{
364	  unsigned int mode = 0; unsigned long size = 0;
365	  long r = stat_host_roundtrip(dirfd, path, flags, &mode, &size);
366	  if (r == 0) {
367	    for (size_t i = 0; i < sizeof(*buf); ++i) ((char*) buf)[i] = 0;
368	    buf->stx_mask = STATX_TYPE | STATX_MODE | STATX_NLINK | STATX_UID |
369	                    STATX_GID | STATX_SIZE;
370	    buf->stx_mode = (unsigned short) mode;
371	    buf->stx_nlink = 1;
372	    buf->stx_size = size;
373	    buf->stx_blksize = 4096;
374	    buf->stx_blocks = (size + 511) / 512;
375	  }
376	  return r;
377	}
