392	/* getcwd(2): the host's VH_SYS_GETCWD returns the buffer's ADDRESS on
393	 * success / 0 on failure (a char*-returning getcwd() convention, shared
394	 * with vplat's own _getcwd), not the Linux syscall's "bytes written
395	 * including NUL" convention -- translate by measuring the string vlinux
396	 * just read back. */
397	static long sys_getcwd(char* buf, unsigned long size)
398	{
399	  uint64_t n = size > WIN_DATA_SIZE ? WIN_DATA_SIZE : size;
400	  intptr_t ret = htif_syscall(VH_SYS_GETCWD, WIN_DATA_VA, n, 0, 0);
401	  if (ret == 0) return -ERANGE;
402	  htif_win_load(buf, 0, n);
403	  size_t len = 0;
404	  while (len < n && buf[len]) ++len;
405	  return (long) (len + 1);
406	}
