424	/* {sec, usec}, both u64 slots -- an 8-aligned, 16-byte (2x8) window load,
425	 * compliant with htif_win_load's alignment contract (see U5's
426	 * host_stat_mode_size comment). Mirrors vplat_syscalls.c's _gettimeofday. */
427	static int host_gettimeofday(long* sec, long* usec)
428	{
429	  if (htif_syscall(VH_SYS_GETTIMEOFDAY, WIN_DATA_VA, 0, 0, 0) != 0) return -1;
430	  uint64_t raw[2];
431	  htif_win_load(raw, 0, sizeof raw);
432	  *sec = (long) raw[0];
433	  *usec = (long) raw[1];
434	  return 0;
435	}
