437	/* CLOCK_MONOTONIC has no dedicated host primitive -- only the wall clock
438	 * VH_SYS_GETTIMEOFDAY exposes. Synthesize it as "elapsed time since this
439	 * process's first monotonic query" (captured lazily, once): never goes
440	 * backward under normal operation, same guarantee real CLOCK_MONOTONIC
441	 * gives, at the cost of losing meaning across a host wall-clock step --
442	 * acceptable here since there is no other clock source to build it from. */
443	static long g_mono_base_sec = -1;
444	static long g_mono_base_usec;
445	
446	static long sys_clock_gettime(int clk, struct vlinux_timespec* tp)
447	{
448	  long sec, usec;
449	  if (host_gettimeofday(&sec, &usec) != 0) return -EINVAL;
450	
451	  if (clk == CLOCK_MONOTONIC) {
452	    if (g_mono_base_sec < 0) {
453	      g_mono_base_sec = sec;
454	      g_mono_base_usec = usec;
455	    }
456	    sec -= g_mono_base_sec;
457	    usec -= g_mono_base_usec;
458	    if (usec < 0) {
459	      usec += 1000000;
460	      sec -= 1;
461	    }
462	  } else if (clk != CLOCK_REALTIME) {
463	    return -EINVAL;
464	  }
465	
466	  tp->tv_sec = sec;
467	  tp->tv_nsec = usec * 1000;
468	  return 0;
469	}
470	
471	static long sys_clock_getres(int clk, struct vlinux_timespec* res)
472	{
473	  if (clk != CLOCK_REALTIME && clk != CLOCK_MONOTONIC) return -EINVAL;
474	  if (res) {
475	    res->tv_sec = 0;
476	    res->tv_nsec = 1000; /* 1us: VH_SYS_GETTIMEOFDAY's real resolution */
477	  }
478	  return 0;
479	}
