481	int handle_ecall(unsigned long* regs)
482	{
483	  const unsigned long nr = regs[REG_A7];
484	  long ret = 0;
485	
486	  switch (nr) {
487	    case SYS_write:
488	      ret = _write((int) regs[REG_A0], (const void*) regs[REG_A1],
489	                  (size_t) regs[REG_A2]);
490	      break;
491	    case SYS_writev:
492	      ret = sys_writev((int) regs[REG_A0],
493	                       (const struct vlinux_iovec*) regs[REG_A1],
494	                       (int) regs[REG_A2]);
495	      break;
496	
497	    case SYS_openat:
498	      ret = sys_openat((int) regs[REG_A0], (const char*) regs[REG_A1],
499	                       (int) regs[REG_A2], (int) regs[REG_A3]);
500	      break;
501	    case SYS_close:
502	      ret = htif_syscall(VH_SYS_CLOSE, regs[REG_A0], 0, 0, 0);
503	      break;
504	    case SYS_read:
505	      ret = _read((int) regs[REG_A0], (void*) regs[REG_A1],
506	                  (size_t) regs[REG_A2]);
507	      break;
508	    case SYS_pread64:
509	      ret = sys_pread64((int) regs[REG_A0], (void*) regs[REG_A1],
510	                        (unsigned long) regs[REG_A2], (long) regs[REG_A3]);
511	      break;
512	    case SYS_lseek:
513	      ret = htif_syscall(VH_SYS_LSEEK, regs[REG_A0], regs[REG_A1],
514	                         regs[REG_A2], 0);
515	      break;
516	    case SYS_fstat:
517	      ret = sys_fstat((int) regs[REG_A0], (struct vlinux_stat*) regs[REG_A1]);
518	      break;
519	    case SYS_fstatat:
520	      ret = sys_fstatat((int) regs[REG_A0], (const char*) regs[REG_A1],
521	                        (struct vlinux_stat*) regs[REG_A2], (int) regs[REG_A3]);
522	      break;
523	    case SYS_statx:
524	      ret = sys_statx((int) regs[REG_A0], (const char*) regs[REG_A1],
525	                      (int) regs[REG_A2], (struct vlinux_statx*) regs[REG_A4]);
526	      break;
527	    case SYS_faccessat:
528	      ret = sys_faccessat((int) regs[REG_A0], (const char*) regs[REG_A1],
529	                          (int) regs[REG_A2]);
530	      break;
531	    case SYS_getcwd:
532	      ret = sys_getcwd((char*) regs[REG_A0], (unsigned long) regs[REG_A1]);
533	      break;
534	    case SYS_fadvise64:
535	    case SYS_madvise:
536	      ret = 0; /* access-pattern hints (readahead/willneed/dontneed, ...):
537	                * everything is already eagerly resident, nothing to tune */
538	      break;
539	    case SYS_readlinkat:
540	      ret = -EINVAL; /* no symlinks in this filesystem relay: never one */
541	      break;
542	    case SYS_getdents64:
543	      ret = -ENOSYS; /* no directory-listing primitive on the HTIF window */
544	      break;
545	
546	    case SYS_clock_gettime:
547	      ret = sys_clock_gettime((int) regs[REG_A0],
548	                              (struct vlinux_timespec*) regs[REG_A1]);
549	      break;
550	    case SYS_clock_getres:
551	      ret = sys_clock_getres((int) regs[REG_A0],
552	                             (struct vlinux_timespec*) regs[REG_A1]);
553	      break;
554	    case SYS_nanosleep:
555	    case SYS_clock_nanosleep:
556	      ret = 0; /* no timer exists: every sleep "completes" immediately,
557	                * burning no sim time (ROADMAP_LINUX_RUNTIME.md U6) */
558	      break;
559	
560	    case SYS_exit:
561	    case SYS_exit_group:
562	      _exit((int) regs[REG_A0]); /* noreturn */
563	
564	    case SYS_brk:
565	      ret = sys_brk(regs[REG_A0]);
566	      break;
567	    case SYS_mmap:
568	      ret = sys_mmap(regs[REG_A0], regs[REG_A1], (long) regs[REG_A2],
569	                     (long) regs[REG_A3], (long) regs[REG_A4],
570	                     (long) regs[REG_A5]);
571	      break;
572	    case SYS_munmap:
573	      ret = sys_munmap(regs[REG_A0], regs[REG_A1]);
574	      break;
575	    case SYS_mprotect:
576	      ret = sys_mprotect(regs[REG_A0], regs[REG_A1], (long) regs[REG_A2]);
577	      break;
578	    case SYS_mremap:
579	      ret = sys_mremap(regs[REG_A0], regs[REG_A1], regs[REG_A2], regs[REG_A3]);
580	      break;
581	
582	    case SYS_set_tid_address:
583	      ret = 1; /* the fixed "tid" every getpid/gettid call also reports */
584	      break;
585	    case SYS_futex:
586	      /* Single hart, single thread (ROADMAP_LINUX_RUNTIME.md: clone is
587	       * -ENOSYS, apps run -t 1): no real contention can ever exist, so
588	       * every op is answered 0 -- FUTEX_WAIT: "already available" (a
589	       * spurious wake glibc's mutex/condvar loops are required by the
590	       * futex(2) contract to tolerate and re-check, so this is spec-legal,
591	       * not a shortcut); FUTEX_WAKE(_BITSET): "0 waiters woken" (there
592	       * are never any real waiters to wake); FUTEX_LOCK_PI/TRYLOCK_PI/
593	       * UNLOCK_PI: "success" (0 is their success code too). Without this,
594	       * glibc's OWN internal locking (malloc arena, static-init guards --
595	       * used pervasively even in a single-threaded process, not just for
596	       * explicit threading) hits ENOSYS and __libc_fatal()s with "The
597	       * futex facility returned an unexpected error code." before
598	       * main() is ever reached. */
599	      ret = 0;
600	      break;
601	    case SYS_set_robust_list:
602	      ret = 0;
603	      break;
604	    case SYS_rseq:
605	      ret = -ENOSYS; /* deliberate: restartable sequences, glibc falls back */
606	      break;
607	
608	    case SYS_uname:
609	      sys_uname((struct vlinux_utsname*) regs[REG_A0]);
610	      ret = 0;
611	      break;
612	
613	    case SYS_getpid:
614	    case SYS_gettid:
615	      ret = 1;
616	      break;
617	    case SYS_getuid:
618	    case SYS_geteuid:
619	    case SYS_getgid:
620	    case SYS_getegid:
621	      ret = 0;
622	      break;
623	
624	    case SYS_sysinfo:
625	      sys_sysinfo((struct vlinux_sysinfo*) regs[REG_A0]);
626	      ret = 0;
627	      break;
628	
629	    case SYS_prlimit64: {
630	      /* {rlim_cur, rlim_max}, both u64 -- old_limit is regs[REG_A3]; report
631	       * unlimited rather than modeling real per-resource limits. */
632	      unsigned long* old_limit = (unsigned long*) regs[REG_A3];
633	      if (old_limit) {
634	        old_limit[0] = ~0ul; /* RLIM_INFINITY */
635	        old_limit[1] = ~0ul;
636	      }
637	      ret = 0;
638	      break;
639	    }
640	    case SYS_getrandom: {
641	      unsigned char* buf = (unsigned char*) regs[REG_A0];
642	      const unsigned long len = regs[REG_A1];
643	      unsigned long seed;
644	      asm volatile("csrr %0, mcycle" : "=r"(seed)); /* see stack.c: mcycle,
645	                                                       * not rdcycle/rdtime */
646	      for (unsigned long i = 0; i < len; ++i) {
647	        seed = seed * 6364136223846793005ul + 1442695040888963407ul;
648	        buf[i] = (unsigned char) (seed >> 33);
649	      }
650	      ret = (long) len;
651	      break;
652	    }
653	
654	    case SYS_sched_getaffinity: {
655	      const unsigned long cpusetsize = regs[REG_A1];
656	      unsigned char* mask = (unsigned char*) regs[REG_A2];
657	      if (cpusetsize < 1) {
658	        ret = -EINVAL;
659	        break;
660	      }
661	      mask[0] = 0x1; /* 1 cpu, bit 0 */
662	      for (unsigned long i = 1; i < cpusetsize; ++i) mask[i] = 0;
663	      ret = (long) cpusetsize;
664	      break;
665	    }
666	    case SYS_sched_yield:
667	      ret = 0; /* nothing else to yield to (single-threaded) */
668	      break;
669	
670	    case SYS_rt_sigaction:
671	    case SYS_rt_sigprocmask:
672	    case SYS_sigaltstack:
673	      ret = 0; /* recorded nowhere: no signal delivery exists to honor them */
674	      break;
675	    case SYS_tgkill:
676	      _exit(128 + (int) regs[REG_A2]); /* noreturn: a fatal signal to self */
677	
678	    case SYS_ioctl:
679	      ret = -ENOTTY; /* every fd here is UART/SimControl, never a real tty */
680	      break;
681	    case SYS_fcntl:
682	      ret = 0; /* basic: accept every fd-flag query/set as a no-op success */
683	      break;
684	
685	    default:
686	      if (!enosys_already_seen(nr)) printf("vlinux: ENOSYS %lu\n", nr);
687	      ret = -ENOSYS;
688	      break;
689	  }
690	
691	  regs[REG_A0] = (unsigned long) ret;
692	  regs[REG_MEPC] += 4; /* skip the ecall on return */
693	  return 1;
694	}
