  1 // Unit tests for the pure cores of `--runtime linux` manifest staging (U2,
  2 // ROADMAP_LINUX_RUNTIME.md): the .manifest blob serializer, the objcopy argv
  3 // builder, and make_temp_dir (a tiny fs helper the staging orchestrator uses).
  4 //
  5 // stage_linux_runtime itself (real copy + objcopy spawn) needs a built
  6 // vlinux.elf + toolchain, so it is exercised at the shell level by
  7 // tests/andes_sim/test_andes_sim_runtime_linux.sh; this file stays pure/fast.
  8 #include <cstdint>
  9 #include <cstring>
 10 #include <string>
 11 #include <vector>
 12 
 13 #include "../runtime/linux/manifest.h"
 14 #include "manifest.hpp"
 15 #include "tempdir.hpp"
 16 #include "test_check.hpp"
 17 
 18 using namespace andes_sim;
 19 using andes_sim::test::check_eq;
 20 
 21 int main() {
 22   // build_manifest_blob: byte-exact struct vlinux_manifest layout, the ABI
 23   // vlinux's own main.c reads (runtime/linux/manifest.h is the one source of
 24   // truth both sides include).
 25   {
 26     std::string err;
 27     std::vector<uint8_t> blob =
 28         build_manifest_blob("/abs/path/app.elf", 1073741824ull, 0, {}, err);
 29     CHECK(err.empty());
 30     CHECK(blob.size() == sizeof(vlinux_manifest));
 31     vlinux_manifest m{};
 32     std::memcpy(&m, blob.data(), sizeof(m));
 33     CHECK(m.magic == VLINUX_MANIFEST_MAGIC);
 34     CHECK(m.version == VLINUX_MANIFEST_VERSION);
 35     CHECK(m.mem_size == 1073741824ull);
 36     CHECK(std::string(m.app_path) == "/abs/path/app.elf");
 37     CHECK(m.argv_extra_count == 0);
 38     CHECK(m.argv_extra_len == 0);
 39     // U10d: guest RAM base rides the manifest so vlinux can place its arenas
 40     // at ram_base + mem_size instead of assuming RAM starts at 0. Today every
 41     // caller passes 0 (identical layout to v2); a non-zero base is what lets
 42     // a >2 GiB guest live in QEMU AE350's DRAM_ALIAS/DRAM_EXT window.
 43     CHECK(m.ram_base == 0);
 44   }
 45 
 46   // U10d: a non-zero base round-trips, and the wire version is 3 (the field
 47   // was appended, so v2 readers would mis-parse -- hence the bump).
 48   {
 49     std::string err;
 50     std::vector<uint8_t> blob = build_manifest_blob(
 51         "/abs/path/app.elf", 6ull * 1024 * 1024 * 1024, 0x800000000ull, {}, err);
 52     CHECK(err.empty());
 53     vlinux_manifest m{};
 54     std::memcpy(&m, blob.data(), sizeof(m));
 55     CHECK(m.version == 3u);
 56     CHECK(m.ram_base == 0x800000000ull);
 57     CHECK(m.mem_size == 6ull * 1024 * 1024 * 1024);
 58   }
 59 
 60   // An app path that does not fit the fixed 256-byte field is an error, not
 61   // a silent truncation (the wire format has no length prefix to recover
 62   // from a cut string).
 63   {
 64     std::string err;
 65     const std::string huge(300, 'x');
 66     std::vector<uint8_t> blob = build_manifest_blob(huge, 0, 0, {}, err);
 67     CHECK(blob.empty());
 68     CHECK(!err.empty());
 69   }
 70 
 71   // A path that exactly fills the field (255 chars + implicit NUL = 256) is
 72   // still fine; 256 chars (no room for the NUL) is not.
 73   {
 74     std::string err;
 75     const std::string exact(255, 'y');
 76     std::vector<uint8_t> blob = build_manifest_blob(exact, 0, 0, {}, err);
 77     CHECK(err.empty());
 78     CHECK(blob.size() == sizeof(vlinux_manifest));
 79 
 80     std::string err2;
 81     const std::string one_over(256, 'y');
 82     CHECK(build_manifest_blob(one_over, 0, 0, {}, err2).empty());
 83     CHECK(!err2.empty());
 84   }
 85 
 86   // Extra argv (U8, "-- -m model.gguf -t 1"): argv[0] stays app_path;
 87   // argv[1..] threads through as a flat NUL-separated buffer + count, the
 88   // ABI stack.c's build_initial_stack walks to build the app's real argv[].
 89   {
 90     std::string err;
 91     std::vector<uint8_t> blob =
 92         build_manifest_blob("/abs/path/llama-completion", 1073741824ull, 0,
 93                             {"-m", "model.gguf", "-t", "1"}, err);
 94     CHECK(err.empty());
 95     CHECK(blob.size() == sizeof(vlinux_manifest));
 96     vlinux_manifest m{};
 97     std::memcpy(&m, blob.data(), sizeof(m));
 98     CHECK(m.argv_extra_count == 4);
 99     const char* p = m.argv_extra_buf;
100     CHECK(std::string(p) == "-m");
101     p += std::strlen(p) + 1;
102     CHECK(std::string(p) == "model.gguf");
103     p += std::strlen(p) + 1;
104     CHECK(std::string(p) == "-t");
105     p += std::strlen(p) + 1;
106     CHECK(std::string(p) == "1");
107     p += std::strlen(p) + 1;
108     CHECK(m.argv_extra_len == static_cast<uint32_t>(p - m.argv_extra_buf));
109   }
110 
111   // More extra args than VLINUX_MANIFEST_ARGV_MAX_COUNT, or args whose
112   // encoded bytes overflow VLINUX_MANIFEST_ARGV_BYTES, are errors -- same
113   // no-silent-truncation discipline as the app_path overflow case above.
114   {
115     std::string err;
116     const std::vector<std::string> too_many(VLINUX_MANIFEST_ARGV_MAX_COUNT + 1,
117                                             "x");
118     CHECK(build_manifest_blob("/a", 0, 0, too_many, err).empty());
119     CHECK(!err.empty());
120   }
121   {
122     std::string err;
123     const std::vector<std::string> huge_arg = {
124         std::string(VLINUX_MANIFEST_ARGV_BYTES, 'z')};
125     CHECK(build_manifest_blob("/a", 0, 0, huge_arg, err).empty());
126     CHECK(!err.empty());
127   }
128 
129   // manifest_objcopy_argv: the exact --update-section invocation staged into
130   // vlinux-run.elf.
131   {
132     std::vector<std::string> argv =
133         manifest_objcopy_argv("/tc/bin/riscv64-unknown-elf-objcopy",
134                               "/wd/manifest.bin", "/wd/vlinux-run.elf");
135     check_eq(argv,
136              {"/tc/bin/riscv64-unknown-elf-objcopy", "--update-section",
137               ".manifest=/wd/manifest.bin", "/wd/vlinux-run.elf"},
138              "objcopy argv");
139   }
140 
141   // make_temp_dir: a fresh, existing directory; two calls never collide.
142   {
143     std::string d1 = make_temp_dir("andesim-linux-test");
144     CHECK(!d1.empty());
145     std::string d2 = make_temp_dir("andesim-linux-test");
146     CHECK(!d2.empty());
147     CHECK(d1 != d2);
148   }
149 
150   return andes_sim::test::report("manifest");
151 }

