  37           std::to_string(sizeof(m.app_path) - 1) + "): " + app_path;
  38     return {};
  39   }
  40   std::memcpy(m.app_path, app_path.c_str(), app_path.size() + 1);  // + NUL
  41 
  42   if (extra_argv.size() > VLINUX_MANIFEST_ARGV_MAX_COUNT) {
  43     err = "too many app args (" + std::to_string(extra_argv.size()) +
  44           ", max " + std::to_string(VLINUX_MANIFEST_ARGV_MAX_COUNT) + ")";
  45     return {};
  46   }
  47   size_t off = 0;
