  49     const size_t need = a.size() + 1;  // + NUL
  50     if (off + need > sizeof(m.argv_extra_buf)) {
  51       err = "app args too long for the manifest (" +
  52             std::to_string(off + need) + " bytes, max " +
  53             std::to_string(sizeof(m.argv_extra_buf)) + ")";
  54       return {};
  55     }
  56     std::memcpy(m.argv_extra_buf + off, a.c_str(), need);
  57     off += need;
  58   }
  59   m.argv_extra_count = static_cast<uint32_t>(extra_argv.size());
  60   m.argv_extra_len = static_cast<uint32_t>(off);
  61 
  62   std::vector<uint8_t> blob(sizeof(m));
  63   std::memcpy(blob.data(), &m, sizeof(m));
  64   return blob;
