   1 // `--runtime linux` manifest staging (U2, ROADMAP_LINUX_RUNTIME.md).
   2 //
   3 // A linux-runtime run boots a per-run COPY of vlinux.elf (the U1 proxy
   4 // kernel) whose .manifest section has been stamped with this run's app path
   5 // + mem size via `objcopy --update-section`. The app ELF itself is never
   6 // booted directly -- vlinux loads it (from U3 onward).
   7 #ifndef ANDESIM_MANIFEST_HPP
   8 #define ANDESIM_MANIFEST_HPP
   9 
  10 #include <cstdint>
  11 #include <string>
  12 #include <vector>
  13 
  14 namespace andes_sim {
  15 
  16 // Serialize the .manifest section blob (runtime/linux/manifest.h's
  17 // struct vlinux_manifest) for one linux-runtime run. `app_path` must fit the
  18 // struct's fixed-size field (incl. NUL terminator); on overflow returns {}
  19 // and sets err. `extra_argv` becomes the app's argv[1..] (argv[0] is always
  20 // app_path) -- more than VLINUX_MANIFEST_ARGV_MAX_COUNT entries, or entries
  21 // whose encoded (NUL-separated) bytes exceed VLINUX_MANIFEST_ARGV_BYTES, is
  22 // an error, same no-silent-truncation discipline as the app_path overflow
  23 // case.
  24 // `ram_base` is guest RAM's first byte (U10d): vlinux derives its arena and
  25 // stack bounds from [ram_base, ram_base + mem_size). Pass 0 for the historical
  26 // flat-from-zero map.
  27 std::vector<uint8_t> build_manifest_blob(const std::string& app_path,
  28                                          uint64_t mem_size,
  29                                          uint64_t ram_base,
  30                                          const std::vector<std::string>& extra_argv,
  31                                          std::string& err);
  32 
  33 // The `objcopy --update-section` argv that stamps `blob_path`'s bytes into
  34 // `vlinux_elf`'s .manifest section, in place. Pure -- testable without
  35 // spawning.
  36 std::vector<std::string> manifest_objcopy_argv(const std::string& objcopy_bin,
  37                                                const std::string& blob_path,
  38                                                const std::string& vlinux_elf);
  39 
  40 // Stage a per-run vlinux.elf carrying this run's manifest: copy the built
  41 // runtime/linux/vlinux.elf into a fresh temp workdir as vlinux-run.elf, write
  42 // the manifest blob, and objcopy --update-section it in place. Needs
  43 // build/runtime/linux/vlinux.elf (scripts/build_all.sh vlinux) and
  44 // HYBRID_TOOLCHAIN (env or config.env, for objcopy). The workdir is NOT
  45 // cleaned up here -- the caller's -bios points at the returned path for the
  46 // life of the run (see ROADMAP_LINUX_RUNTIME.md U2 for the tradeoff: fast's
  47 // transparent exec_passthrough never returns to clean up after itself, the
  48 // same way run_plan's own staged qemu.cfg is never revisited post-spawn).
  49 // Returns the staged ELF's path, or "" and sets `err`.
  50 std::string stage_linux_runtime(const std::string& app_elf_abs,
  51                                 uint64_t mem_size,
  52                                 uint64_t ram_base,
  53                                 const std::vector<std::string>& extra_argv,
  54                                 std::string& err);
  55 
  56 }  // namespace andes_sim
  57 
  58 #endif  // ANDESIM_MANIFEST_HPP

