======== tests/fixtures/rt_linux_argv.c
   1 /* rt_linux_argv: a -nostdlib Linux-ABI test fixture for
   2  * ROADMAP_LINUX_RUNTIME.md U3 (vlinux's ELF loader + initial stack + auxv).
   3  *
   4  * No libc, no crt0: a naked _start reads argc/argv/envp/auxv straight off
   5  * the incoming sp -- the Linux process-startup ABI vlinux's stack builder
   6  * produces -- and issues raw `ecall`s for write(1,...)/exit_group, the same
   7  * 2 syscalls U3's minimal ecall dispatch handles. It links against nothing,
   8  * so it needs no glibc/linux toolchain (that arrives at U4); the ordinary
   9  * bare-metal HYBRID_TOOLCHAIN builds it, same as every other asm fixture.
  10  *
  11  * Prints "argv[N]=<value>" per argv entry, then "AT_PAGESZ=<value>", then
  12  * exit_group(0).
  13  */
  14 
  15 #define SYS_write 64
  16 #define SYS_exit_group 94
  17 #define AUXV_AT_PAGESZ 6
  18 
  19 static long sys3(long nr, long a0, long a1, long a2)
  20 {
  21   register long a7 asm("a7") = nr;
  22   register long r0 asm("a0") = a0;
  23   register long r1 asm("a1") = a1;
  24   register long r2 asm("a2") = a2;
  25   asm volatile("ecall" : "+r"(r0) : "r"(a7), "r"(r1), "r"(r2) : "memory");
  26   return r0;
  27 }
  28 
  29 static void wr(const char* s, long n)
  30 {
  31   sys3(SYS_write, 1, (long) s, n);
  32 }
  33 
  34 static long len(const char* s)
  35 {
  36   long n = 0;
  37   while (s[n]) ++n;
  38   return n;
  39 }
  40 
  41 /* Decimal-format `v` into buf (no libc itoa); returns the string length. */
  42 static int fmt_u(unsigned long v, char* buf)
  43 {
  44   char tmp[20];
  45   int n = 0;
  46   if (v == 0) tmp[n++] = '0';
  47   while (v) {
