  57   if (clock_getres(CLOCK_MONOTONIC, &res) != 0) {
  58     printf("TIME: clock_getres failed\n");
  59     _exit(1);
  60   }
  61   printf("TIME: clock_getres ok\n");
  62 
  63   struct timespec req = {0, 1000}; /* 1us: returns immediately, no timer exists */
  64   if (nanosleep(&req, NULL) != 0) {
  65     printf("TIME: nanosleep failed\n");
  66     _exit(1);
  67   }
  68   printf("TIME: nanosleep ok\n");
  69 
  70   if (clock_nanosleep(CLOCK_MONOTONIC, 0, &req, NULL) != 0) {
