   1 /* U7 contract (ROADMAP_LINUX_RUNTIME.md): file-backed MAP_PRIVATE mmap --
   2  * llama.cpp's default GGUF load path. mmap a host file, checksum it,
   3  * partially munmap (llama unmaps unused tail ranges), verify the
   4  * remainder is intact, then confirm mremap is refused (ENOMEM) rather
   5  * than corrupting anything.
   6  *
   7  * File size: the roadmap's own illustrative figure is 64 MB, sized for
   8  * the fast leg. This fixture also runs on the cycle-accurate leg, where
   9  * each window round trip costs real simulated cycles (see U6's 10M-loop
  10  * lesson) -- measured directly (256 KB, ~258 round trips, hung past a
  11  * 600s timeout; 4 KB, ~6 round trips, completed in 435s, matching the
  12  * ~7min glibc-startup baseline U4/U5/U6 already measured almost exactly):
  13  * 16 KB is large enough to span ~9 window chunks each way -- still
  14  * meaningfully multi-chunk, not a single round trip -- while leaving
  15  * comfortable cycle-leg headroom.
  16  */
  17 #define _GNU_SOURCE
  18 #include <errno.h>
  19 #include <fcntl.h>
  20 #include <stdio.h>
  21 #include <stdlib.h>
  22 #include <string.h>
  23 #include <sys/mman.h>
  24 #include <unistd.h>
  25 
  26 #define FILE_SIZE (16 * 1024)
  27 
  28 static unsigned checksum(const unsigned char* p, size_t n)
  29 {
  30   unsigned c = 0;
  31   for (size_t i = 0; i < n; ++i) c = c * 131 + p[i];
  32   return c;
  33 }
  34 
  35 int main(void)
  36 {
  37   setvbuf(stdout, NULL, _IONBF, 0); /* see rt_linux_file.c: no tty here */
  38 
  39   const char* path = "rt_linux_mmap_test.tmp";
  40   unsigned char* pattern = malloc(FILE_SIZE);
  41   if (!pattern) {
  42     printf("MMAP: malloc(pattern) failed\n");
  43     _exit(1);
  44   }
  45   for (size_t i = 0; i < FILE_SIZE; ++i) pattern[i] = (unsigned char) (i * 37 + 11);
  46   unsigned want = checksum(pattern, FILE_SIZE);
  47 
  48   FILE* f = fopen(path, "w");
  49   if (!f) {
  50     printf("MMAP: fopen(w) failed\n");
  51     _exit(1);
  52   }
  53   if (fwrite(pattern, 1, FILE_SIZE, f) != FILE_SIZE) {
  54     printf("MMAP: short write\n");
  55     _exit(1);
  56   }
  57   fclose(f);
  58 
  59   int fd = open(path, O_RDONLY);
  60   if (fd < 0) {
  61     printf("MMAP: open failed\n");
  62     _exit(1);
  63   }
  64 
  65   void* map = mmap(NULL, FILE_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
  66   if (map == MAP_FAILED) {
  67     printf("MMAP: mmap failed errno=%d\n", errno);
  68     _exit(1);
  69   }
  70 
  71   unsigned got = checksum((const unsigned char*) map, FILE_SIZE);
  72   if (got != want) {
  73     printf("MMAP: checksum mismatch want=%u got=%u\n", want, got);
  74     _exit(1);
  75   }
  76   printf("MMAP: checksum ok (%u)\n", got);
  77 
  78   /* Partial unmap: llama.cpp unmaps unused tail ranges. The first half
  79    * must stay valid and unchanged. */
  80   if (munmap((char*) map + FILE_SIZE / 2, FILE_SIZE / 2) != 0) {
  81     printf("MMAP: partial munmap failed\n");
  82     _exit(1);
  83   }
  84   unsigned got_half = checksum((const unsigned char*) map, FILE_SIZE / 2);
  85   unsigned want_half = checksum(pattern, FILE_SIZE / 2);
  86   if (got_half != want_half) {
  87     printf("MMAP: first half corrupted after partial munmap\n");
  88     _exit(1);
  89   }
  90   printf("MMAP: partial munmap ok, remaining half intact\n");
  91 
  92   if (munmap(map, FILE_SIZE / 2) != 0) {
  93     printf("MMAP: full munmap failed\n");
  94     _exit(1);
  95   }
  96   printf("MMAP: full munmap ok\n");
  97 
  98   void* map2 = mmap(NULL, FILE_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
  99   if (map2 == MAP_FAILED) {
 100     printf("MMAP: second mmap failed\n");
 101     _exit(1);
 102   }
 103   errno = 0;
 104   void* remapped = mremap(map2, FILE_SIZE, FILE_SIZE * 2, 0);
 105   if (remapped != MAP_FAILED || errno != ENOMEM) {
 106     printf("MMAP: mremap unexpected result errno=%d\n", errno);
 107     _exit(1);
 108   }
 109   printf("MMAP: mremap correctly ENOMEM\n");
